const item = $input.first().json;
const body = item.body || item;

const raw_name = String(body.patient_name || body.name || "").trim();

// 1. Transliterate Eastern Arabic-Indic numerals (٠-٩) to ASCII (0-9)
let raw_phone = String(body.patient_phone || body.phone || "").trim();
raw_phone = raw_phone.replace(/[٠-٩]/g, d => "٠١٢٣٤٥٦٧٨٩".indexOf(d));

// 2. Strip whitespace, hyphens, periods, parentheses
raw_phone = raw_phone.replace(/[\s\-\(\)\.]/g, '');

// 3. Normalize international Egyptian prefixes (+20, 0020, leading 20) to standard local format 01...
if (raw_phone.startsWith('+20')) {
  raw_phone = raw_phone.slice(3);
  if (!raw_phone.startsWith('0')) raw_phone = '0' + raw_phone;
} else if (raw_phone.startsWith('0020')) {
  raw_phone = raw_phone.slice(4);
  if (!raw_phone.startsWith('0')) raw_phone = '0' + raw_phone;
} else if (raw_phone.startsWith('+')) {
  raw_phone = raw_phone.slice(1);
} else if (raw_phone.startsWith('200') && raw_phone.length === 13) {
  raw_phone = '0' + raw_phone.slice(3);
} else if (raw_phone.startsWith('20') && raw_phone.length === 12) {
  raw_phone = '0' + raw_phone.slice(2);
}

const context_topic = String(body.context_topic || body.topic || body.case || "استشارة عامة لعناية الجروح والندبات").trim();
const channel = String(body.channel || "whatsapp").trim();
const promo_code = "HT10";
const source = String(body.source || "صفحة الاستشارة wa.html").trim();
const page_url = String(body.page_url || "https://medon90ae.github.io/healing-touch-egypt/wa.html").trim();

// Egyptian phone regex validation: strictly 11 digits starting with 010, 011, 012, or 015
const egyptian_phone_regex = /^01[0125][0-9]{8}$/;
const is_valid_phone = egyptian_phone_regex.test(raw_phone);
const is_valid_name = raw_name.length >= 2;

let normalized_phone = "";
if (is_valid_phone) {
  normalized_phone = "20" + raw_phone.slice(1); // converts 01xxxxxxxxx to E.164 201xxxxxxxxx
}

const is_valid = is_valid_phone && is_valid_name;
const validation_error = !is_valid_name ? "الاسم يجب أن يتكون من حرفين على الأقل" : (!is_valid_phone ? "رقم الهاتف غير صحيح، يجب أن يتكون من 11 رقماً مصرياً يبدأ بـ 01" : null);

return [{
  json: {
    is_valid,
    validation_error,
    patient_name: raw_name,
    patient_phone: raw_phone,
    normalized_phone,
    context_topic,
    channel,
    promo_code,
    promo_benefit: "شحن مجاني + حق فتح ومعاينة الشحنة قبل الدفع",
    source,
    page_url,
    lead_id: `HT-LEAD-${Date.now()}`,
    timestamp: new Date().toISOString(),
    retry_attempt: 0,
    wa_direct_url: normalized_phone ? `https://wa.me/201155803307?text=${encodeURIComponent(`أهلاً بحضرتك، أنا ${raw_name} وسجلت استشارة بخصوص (${context_topic}) بكود خصم HT10`)}` : ""
  }
}];

const item = $input.first().json;
const attempt = (item.retry_attempt || 0) + 1;
const max_retries = 3;
return [{
  json: {
    ...item,
    retry_attempt: attempt,
    max_retries,
    has_retries_left: attempt <= max_retries
  }
}];

return [{
  json: {
    status: "CRM_APPEND_FAILED_AFTER_RETRIES",
    lead_id: $('Validate & Normalize Patient Lead').first().json.lead_id,
    patient_name: $('Validate & Normalize Patient Lead').first().json.patient_name,
    patient_phone: $('Validate & Normalize Patient Lead').first().json.patient_phone,
    escalated_at: new Date().toISOString()
  }
}];
